from collections import deque

class MyStackBrute:
    def __init__(self):
        self.q1 = deque()

    def push(self, x):
        q2 = deque()
        q2.append(x)
        while self.q1:
            q2.append(self.q1.popleft())            # move everything into q2, behind x
        self.q1 = q2                                  # x is now at the front

    def pop(self):
        return self.q1.popleft()

    def top(self):
        return self.q1[0]

    def empty(self):
        return len(self.q1) == 0

