import java.util.*;

class MyStackBrute {
    Queue<Integer> q1 = new LinkedList<>();

    void push(int x) {
        Queue<Integer> q2 = new LinkedList<>();
        q2.add(x);
        while (!q1.isEmpty()) q2.add(q1.poll());     // move everything into q2, behind x
        q1 = q2;                                        // x is now at the front
    }

    int pop() { return q1.poll(); }
    int top() { return q1.peek(); }
    boolean empty() { return q1.isEmpty(); }
}

