        q2.push(x);
        while (!q1.empty()) { q2.push(q1.front()); q1.pop(); }  // move everything into q2, behind x
        q1 = q2;                                                  // x is now at the front
    }

    int pop() { int v = q1.front(); q1.pop(); return v; }
    int top() { return q1.front(); }
    bool empty() { return q1.empty(); }
};

