using namespace std;

class MyStack {
public:
    queue<int> q;

    void push(int x) {
        q.push(x);
        for (int i = 0; i < (int)q.size() - 1; i++) {     // rotate size-1 times
            q.push(q.front());
            q.pop();
        }
    }

    int pop() { int v = q.front(); q.pop(); return v; }
    int top() { return q.front(); }
    bool empty() { return q.empty(); }
};
